begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values ('93000000-0000-0000-0000-000000000001','marketing.integrity@test.invalid','{}');
insert into public.profile_roles(profile_id,role_id) values ('93000000-0000-0000-0000-000000000001','administrator') on conflict do nothing;
insert into public.campaigns(id,name) values ('93000000-0000-0000-0000-000000000002','Keep this campaign');
insert into public.posts(id,title,campaign_id,created_by,status,provider_ids) values
('93000000-0000-0000-0000-000000000003','Local title','93000000-0000-0000-0000-000000000002','93000000-0000-0000-0000-000000000001','published','{"facebook":"page_post","instagram":"keep"}');
select public.sync_facebook_post('{"caption":"Synced","media":[],"provider_ids":{"facebook":"page_post"},"likes":3}', '93000000-0000-0000-0000-000000000001');
select is((select title from public.posts where provider_ids->>'facebook'='page_post'),'Local title','sync preserves title');
select is((select campaign_id from public.posts where provider_ids->>'facebook'='page_post'),'93000000-0000-0000-0000-000000000002'::uuid,'sync preserves campaign');
select is((select provider_ids->>'instagram' from public.posts where provider_ids->>'facebook'='page_post'),'keep','sync preserves other providers');
select public.sync_facebook_post('{"caption":"Again","media":[],"provider_ids":{"facebook":"page_post"},"likes":4}', '93000000-0000-0000-0000-000000000001');
select is((select count(*) from public.posts where provider_ids->>'facebook'='page_post'),1::bigint,'repeated sync converges');
select throws_ok($$insert into public.posts(provider_ids) values ('{"facebook":"page_post"}')$$,'23505',null,'unique provider identity enforced');
select ok(not has_function_privilege('authenticated','public.sync_facebook_post(jsonb,uuid)','execute'),'browser cannot invoke privileged sync');
set local role authenticated;
set local request.jwt.claims='{"sub":"93000000-0000-0000-0000-000000000001","role":"authenticated"}';
select throws_ok($$update public.posts set status='draft' where id='93000000-0000-0000-0000-000000000003'$$,'42501',null,'even browser administrators cannot forge lifecycle');
select throws_ok($$update public.posts set likes=999 where id='93000000-0000-0000-0000-000000000003'$$,'42501',null,'metrics are protected');
select throws_ok($$update public.posts set provider_ids='{}' where id='93000000-0000-0000-0000-000000000003'$$,'42501',null,'provider identity protected');
select throws_ok($$update public.posts set caption='tampered' where id='93000000-0000-0000-0000-000000000003'$$,'42501',null,'published content locked');
select lives_ok($$update public.posts set campaign_id=null where id='93000000-0000-0000-0000-000000000003'$$,'campaign assignment remains available');
select throws_ok($$insert into public.posts(status,created_by) values ('published',auth.uid())$$,'42501',null,'browser cannot insert fake published post');
select throws_ok($$select public.save_marketing_post(null,'{"status":"published"}')$$,'22023',null,'save command rejects forged publication');
select throws_ok($$select public.save_marketing_post(null,'{"likes":999}')$$,'22023',null,'save command rejects protected columns');
select throws_ok($$select public.save_marketing_post(null,'{"status":"scheduled","publish_at":"2000-01-01"}')$$,'22023',null,'past schedule rejected');
select lives_ok($$select public.save_marketing_post(null,'{"title":"Draft","status":"draft"}')$$,'draft command works');
select lives_ok($$select public.save_marketing_post(null,jsonb_build_object('title','Scheduled','status','scheduled','publish_at',now()+interval '1 day'))$$,'validated scheduling works');
select throws_ok($$update public.posts set title='changed' where title='Scheduled'$$,'42501',null,'scheduled content locked');
select throws_ok($$select public.save_marketing_post((select id from public.posts where title='Scheduled'),'{"status":"draft"}')$$,'42501',null,'save cannot unlock scheduled post');
select * from finish();
rollback;
